Caza de IOC.ejemplo:
// Barrido de hashes e IPs de campaña en logs de EDR y DNS (KQL)
let MaliciousHashes = dynamic(["e3b0c44298fc1c149afbf4c8996fb924..."]);
let MaliciousDomains = dynamic(["cdn-update-telemetry[.]example"]);
union
(DeviceProcessEvents | where SHA256 in (MaliciousHashes)),
(DeviceNetworkEvents | where RemoteUrl has_any (MaliciousDomains))
| project Timestamp, DeviceName, ActionType, FileName, RemoteUrl
